-- Initial file generated by Claude Sonnet 5.5

module Zocalo.Common.ContentDispositionSpec(tests) where

import Test.Framework(Test, testGroup)
import Test.Framework.Providers.HUnit(testCase)
import Test.HUnit(assertBool, (@?=))

import Zocalo.Common.ContentDisposition(mkDispositionHeader)

import qualified Data.ByteString as BS


tests :: Test
tests =
  testGroup "Zocalo.Common.ContentDisposition"
    [ testCase "plain names: the fallback is the name itself, and the exact name is percent-encoded" $
        mkDispositionHeader "Period 3.zip" @?= "attachment; filename=\"Period 3.zip\"; filename*=UTF-8''Period%203.zip"

    , testCase "quotes and backslashes cannot break out of the quoted string" $
        mkDispositionHeader "a\"b\\c.zip" @?= "attachment; filename=\"a_b_c.zip\"; filename*=UTF-8''a%22b%5Cc.zip"

    , testCase "non-ASCII characters get an underscore fallback plus an exact UTF-8 form" $
        mkDispositionHeader "Caf\233.zip" @?= "attachment; filename=\"Caf_.zip\"; filename*=UTF-8''Caf%C3%A9.zip"

    , testCase "line breaks cannot be smuggled into the header" $ do
        let value = mkDispositionHeader "a\r\nSet-Cookie: x=1"
        assertBool "CR must not appear" $ not $ BS.elem 13 value
        assertBool "LF must not appear" $ not $ BS.elem 10 value
    ]
